import test from 'node:test';import assert from 'node:assert/strict';
import {createRenderer} from '../renderer.js';import {initialState} from '../engine.js';
function fixture(onError){let next,fail=false;const old=globalThis.requestAnimationFrame;globalThis.requestAnimationFrame=fn=>{next=fn;};const c=new Proxy({measureText:s=>({width:s.length*9}),createRadialGradient:()=>({addColorStop(){}}),fillRect(){if(fail){fail=false;throw Error('Falha Canvas simulada');}},ellipse(x,y,rx,ry){if(rx<0||ry<0)throw Error('Raio negativo');}},{get:(o,k)=>k in o?o[k]:()=>{},set:(o,k,v)=>(o[k]=v,true)});const s=initialState(),r=createRenderer({getContext:()=>c},()=>s,{onError});return {r,s,frame:t=>next(t),fail:()=>{fail=true;},close(){r.stop();globalThis.requestAnimationFrame=old;}};}
test('falha Canvas rejeita animação e próxima mensagem continua renderizando',async()=>{let errors=0;const f=fixture(()=>errors++);try{const first=f.r.animate({type:'spawn'});f.fail();f.frame(performance.now()+100);await assert.rejects(first,/Canvas/);assert.equal(errors,1);const next=f.r.animate({type:'spawn'});f.frame(performance.now()+1000);await next;assert.equal(errors,1);}finally{f.close();}});
test('frame anterior ao início não cria raio negativo nem bloqueia animação',async()=>{const f=fixture(()=>assert.fail('Frame inválido'));try{const done=f.r.animate({type:'spawn'});f.frame(performance.now()-100);f.frame(performance.now()+1000);await done;}finally{f.close();}});
test('animação conclui mesmo sem receber frames e cancelamento rejeita viagem pendente',async()=>{const f=fixture(()=>{});try{let finished=false;f.r.animate({type:'spawn'}).then(()=>{finished=true;});await new Promise(resolve=>setTimeout(resolve,1000));assert.equal(finished,true);const trip=f.r.transition({scene:'shop'},()=>assert.fail('Destino não deve ser aplicado'));f.r.cancelPending(new Error('Cancelado pelo jogador'));await assert.rejects(trip,/Cancelado/);assert.equal(f.r.getTravel(),null);}finally{f.close();}});
